<form method="post" class="panel editor-form"><?= csrf_field() ?><div class="form-grid"><label class="full">عنوان پروژه<input name="title" value="<?= e($project['title']??'') ?>" required></label><label>نشانی<input name="slug" value="<?= e($project['slug']??'') ?>"></label><label>وضعیت<select name="status"><option value="draft" <?= ($project['status']??'draft')==='draft'?'selected':'' ?>>پیش‌نویس</option><option value="published" <?= ($project['status']??'')==='published'?'selected':'' ?>>منتشرشده</option></select></label><label class="full">خلاصه<input name="summary" maxlength="500" value="<?= e($project['summary']??'') ?>"></label><label class="full">توضیحات<textarea name="description" rows="6"><?= e($project['description']??'') ?></textarea></label><label>وب‌سایت<input type="url" name="website_url" value="<?= e($project['website_url']??'') ?>" placeholder="https://"></label><label>مخزن GitHub<input type="url" name="repository_url" value="<?= e($project['repository_url']??'') ?>" placeholder="https://github.com/..."></label><label class="check-label"><input type="checkbox" name="featured" value="1" <?= !empty($project['featured'])?'checked':'' ?>> پروژه ویژه</label></div><div class="form-actions"><a class="button ghost" href="<?= e(url('admin/projects')) ?>">بازگشت</a><button class="button primary" type="submit">ذخیره پروژه</button></div></form>
